// In frontend/src/DataChart.js

import React, { useState, useEffect, useRef } from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS, CategoryScale, LinearScale, PointElement,
  LineElement, Title, Tooltip, Legend, TimeScale
} from 'chart.js';
import 'chartjs-adapter-date-fns';
import { generateColorGradient } from './colorUtils';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, TimeScale);

const pidColors = {
    pid1: { main: '#00FFFF', dark: '#008b8b' }, // Cyan
    pid2: { main: '#FF00FF', dark: '#8B008B' }, // Magenta
    pid3: { main: '#00FF00', dark: '#006400' }, // Green
};

const DataChart = ({ groupData, onTimeRangeChange }) => {
    const chartRef = useRef(null);
    const [zoom, setZoom] = useState(10); // Default to 10 minutes
    const [selectedPids, setSelectedPids] = useState({
        pid1: 'Engine RPM', // Default PID
        pid2: 'None',
        pid3: 'None',
    });

    // Create datasets for the chart based on selected PIDs and logs
    const datasets = Object.entries(selectedPids)
        .filter(([, pidName]) => pidName && pidName !== 'None')
        .flatMap(([pidKey, pidName], pidIndex) => {
            const numLogs = groupData.logs.length;
            const colors = generateColorGradient(pidColors[pidKey].main, pidColors[pidKey].dark, numLogs);

            return groupData.logs.map((log, logIndex) => {
                const logId = log.log_id;
                const logData = groupData.all_data[logId] || [];
                const logColumns = groupData.all_columns[logId] || [];
                const pidSanitized = logColumns.find(c => c.toLowerCase().replace(/[\s\W]/g, '_') === pidName.toLowerCase().replace(/[\s\W]/g, '_'));

                const data = logData.map(d => ({
                    x: d.timestamp,
                    y: d[pidSanitized]
                }));

                return {
                    label: `${log.file_name} - ${pidName}`,
                    data: data,
                    borderColor: colors[logIndex],
                    backgroundColor: colors[logIndex],
                    yAxisID: `y${pidIndex + 1}`,
                    tension: 0.2,
                    pointRadius: 0,
                    borderWidth: 2,
                };
            });
        });

    const handlePidChange = (pidKey, value) => {
        setSelectedPids(prev => ({ ...prev, [pidKey]: value }));
    };

    const handleZoomChange = (newZoom) => {
        setZoom(newZoom);
        const chart = chartRef.current;
        if (!chart) return;

        const fullMin = Math.min(...groupData.logs.flatMap(log => groupData.all_data[log.log_id].map(d => d.timestamp)));
        chart.options.scales.x.min = fullMin;
        chart.options.scales.x.max = fullMin + (newZoom * 60 * 1000);
        chart.update();
        onTimeRangeChange({ min: chart.options.scales.x.min, max: chart.options.scales.x.max });
    };

    const options = {
        responsive: true,
        maintainAspectRatio: false,
        interaction: { mode: 'index', intersect: false },
        stacked: false,
        plugins: {
            title: { display: true, text: 'Trip Group Log Comparison' },
            zoom: {
                pan: { enabled: true, mode: 'x' },
                zoom: { wheel: { enabled: true }, mode: 'x', pinch: { enabled: true } },
            },
        },
        scales: {
            x: {
                type: 'time',
                time: { unit: 'second' },
                ticks: { source: 'auto' },
                title: { display: true, text: 'Time' },
            },
            y1: {
                type: 'linear',
                display: selectedPids.pid1 !== 'None',
                position: 'left',
                title: { display: true, text: selectedPids.pid1, font: { size: 14 }, color: pidColors.pid1.main },
                ticks: { color: pidColors.pid1.main },
            },
            y2: {
                type: 'linear',
                display: selectedPids.pid2 !== 'None',
                position: 'left',
                grid: { drawOnChartArea: false },
                title: { display: true, text: selectedPids.pid2, font: { size: 14 }, color: pidColors.pid2.main },
                ticks: { color: pidColors.pid2.main },
            },
            y3: {
                type: 'linear',
                display: selectedPids.pid3 !== 'None',
                position: 'right',
                grid: { drawOnChartArea: false },
                title: { display: true, text: selectedPids.pid3, font: { size: 14 }, color: pidColors.pid3.main },
                ticks: { color: pidColors.pid3.main },
            },
        },
        onHover: (event, chartElement) => {
            const chart = chartRef.current;
            if (chart && chart.options.scales.x.min && chart.options.scales.x.max) {
                 onTimeRangeChange({ min: chart.options.scales.x.min, max: chart.options.scales.x.max });
            }
        }
    };

    // Set initial zoom on first render
    useEffect(() => {
        if (groupData) handleZoomChange(10);
    }, [groupData]);

    const pidSelector = (pidKey) => (
        <select value={selectedPids[pidKey]} onChange={(e) => handlePidChange(pidKey, e.target.value)} style={{ borderColor: pidColors[pidKey].main, color: pidColors[pidKey].main, marginRight: '10px' }}>
            <option>None</option>
            {groupData.combined_pids.map(pid => <option key={pid} value={pid}>{pid}</option>)}
        </select>
    );

    return (
        <div>
            <div className="controls" style={{ padding: '10px', display: 'flex', justifyContent: 'space-between' }}>
                <div>
                    {pidSelector('pid1')}
                    {pidSelector('pid2')}
                    {pidSelector('pid3')}
                </div>
                <div>
                    <span>Zoom: </span>
                    <button onClick={() => handleZoomChange(2)}>2m</button>
                    <button onClick={() => handleZoomChange(5)}>5m</button>
                    <button onClick={() => handleZoomChange(10)}>10m</button>
                </div>
            </div>
            <div style={{ height: '480px' }}> {/* 20% taller */}
                <Line ref={chartRef} options={options} data={{ datasets }} />
            </div>
        </div>
    );
};

export default DataChart;
